  'home.process.step1.title': { en: 'Briefing', de: 'Briefing', es: 'Briefing', pt: 'Briefing', fr: 'Briefing', it: 'Briefing' },
  'home.process.step1.desc': { en: 'Tell us the series, the game and the calendar. You get a production plan and a fixed quote back — usually within a few days.', de: 'Sagen Sie uns Serie, Simulation und Rennkalender. Sie bekommen einen Produktionsplan und ein verbindliches Angebot zurück — in der Regel innerhalb weniger Tage.', es: 'Cuéntenos la serie, el juego y el calendario. Recibirá un plan de producción y un presupuesto cerrado, normalmente en pocos días.', pt: 'Conte-nos a série, o jogo e o calendário. Você recebe um plano de produção e um orçamento fechado — normalmente em poucos dias.', fr: 'Indiquez-nous la série, le jeu et le calendrier. Vous recevez un plan de production et un devis ferme, généralement sous quelques jours.', it: 'Raccontaci la serie, il gioco e il calendario. Ricevi un piano di produzione e un preventivo fisso, di norma in pochi giorni.' },
  'home.process.step2.title': { en: 'Production', de: 'Produktion', es: 'Producción', pt: 'Produção', fr: 'Production', it: 'Produzione' },
  'home.process.step2.desc': { en: 'Graphics package, commentary team, timing integration, multi-language feeds. Built once, then run every race weekend.', de: 'Grafikpaket, Kommentatorenteam, Timing-Anbindung, mehrsprachige Feeds. Einmal aufgebaut, dann an jedem Rennwochenende gefahren.', es: 'Paquete gráfico, equipo de comentaristas, integración de tiempos, señales multiidioma. Se construye una vez y se opera cada fin de semana de carrera.', pt: 'Pacote gráfico, equipe de comentários, integração de tempos, sinais multilíngues. Montado uma vez e operado a cada fim de semana de corrida.', fr: 'Habillage graphique, équipe de commentateurs, intégration du chronométrage, flux multilingues. Construit une fois, puis opéré chaque week-end de course.', it: 'Pacchetto grafico, team di telecronaca, integrazione dei tempi, feed multilingua. Costruito una volta e poi gestito ogni weekend di gara.' },
  'home.process.step3.title': { en: 'On air', de: 'Auf Sendung', es: 'Al aire', pt: 'No ar', fr: 'À l\'antenne', it: 'In onda' },
  'home.process.step3.desc': { en: 'Live on your channels and ours, with highlights and clips afterwards. You get the numbers; we handle everything in between.', de: 'Live auf Ihren und unseren Kanälen, danach Highlights und Clips. Sie bekommen die Zahlen — alles dazwischen übernehmen wir.', es: 'En directo en sus canales y en los nuestros, con resúmenes y clips después. Usted recibe las cifras; nosotros nos ocupamos de todo lo demás.', pt: 'Ao vivo nos seus canais e nos nossos, com melhores momentos e clipes depois. Você recebe os números; nós cuidamos de todo o resto.', fr: 'En direct sur vos chaînes et les nôtres, avec résumés et extraits ensuite. Vous recevez les chiffres, nous gérons tout le reste.', it: 'In diretta sui vostri canali e sui nostri, con highlight e clip a seguire. Voi ricevete i numeri, noi gestiamo tutto il resto.' },
  'home.process.cta': { en: 'Request a quote', de: 'Angebot anfragen', es: 'Solicitar presupuesto', pt: 'Solicitar orçamento', fr: 'Demander un devis', it: 'Richiedi un preventivo' },

