  'contact.err.select':    { en: 'Please choose an option.', de: 'Bitte wählen Sie eine Option.', es: 'Por favor, elija una opción.', pt: 'Por favor, escolha uma opção.', fr: 'Veuillez choisir une option.', it: 'Scegli un\'opzione.' },
