  'contact.err.dateRange': { en: 'The end date cannot be before the start date.', de: 'Das Enddatum kann nicht vor dem Startdatum liegen.', es: 'La fecha de fin no puede ser anterior a la de inicio.', pt: 'A data de fim não pode ser anterior à de início.', fr: 'La date de fin ne peut pas précéder la date de début.', it: 'La data di fine non può precedere quella di inizio.' },
  'contact.err.turnstile': { en: 'Please complete the security check.', de: 'Bitte schließen Sie die Sicherheitsprüfung ab.', es: 'Complete la verificación de seguridad.', pt: 'Conclua a verificação de segurança.', fr: 'Veuillez effectuer la vérification de sécurité.', it: 'Completa il controllo di sicurezza.' },
  'contact.err.turnstileFailed': { en: 'Security verification failed. Please try again.', de: 'Sicherheitsprüfung fehlgeschlagen. Bitte versuchen Sie es erneut.', es: 'La verificación de seguridad falló. Inténtelo de nuevo.', pt: 'A verificação de segurança falhou. Tente novamente.', fr: 'La vérification de sécurité a échoué. Veuillez réessayer.', it: 'Verifica di sicurezza non riuscita. Riprova.' },
  'contact.err.rateLimit': { en: 'Too many messages from your connection. Please try again in an hour or email us directly at contact@racespot.tv', de: 'Zu viele Nachrichten von Ihrer Verbindung. Bitte versuchen Sie es in einer Stunde erneut oder schreiben Sie direkt an contact@racespot.tv', es: 'Demasiados mensajes desde su conexión. Inténtelo en una hora o escríbanos a contact@racespot.tv', pt: 'Muitas mensagens da sua conexão. Tente novamente em uma hora ou escreva para contact@racespot.tv', fr: 'Trop de messages depuis votre connexion. Réessayez dans une heure ou écrivez-nous à contact@racespot.tv', it: 'Troppi messaggi dalla tua connessione. Riprova tra un\'ora o scrivi a contact@racespot.tv' },
  'contact.err.server':    { en: 'We could not send your message. Please try again or email us directly at contact@racespot.tv', de: 'Ihre Nachricht konnte nicht gesendet werden. Bitte versuchen Sie es erneut oder schreiben Sie direkt an contact@racespot.tv', es: 'No pudimos enviar su mensaje. Inténtelo de nuevo o escríbanos a contact@racespot.tv', pt: 'Não foi possível enviar sua mensagem. Tente novamente ou escreva para contact@racespot.tv', fr: 'Votre message n\'a pas pu être envoyé. Réessayez ou écrivez-nous à contact@racespot.tv', it: 'Non siamo riusciti a inviare il messaggio. Riprova o scrivi a contact@racespot.tv' },

